void add(int u, int v) { e[++tot] = {v, h[u]}; h[u] = tot; }

inline I R(I a, I b)
{
	if (isempty(a)) { return b; }
	if (isempty(b)) { return a; }
	return MR(a, b);
}

inline I C(I a, I b)
{
	if (isempty(a)) { return b; }
	if (isempty(b)) { return a; }
	return MC(a, b);
