vector<info> merge(vector<int> a, vector<vector<info>> b, int m = -1) {
	static info v[N];
	static int l[N], r[N];
	int n = a.size();
	if (m == -1)
		m = 1 << 30;

	if (n == 1 && b[0].size() <= 1)
		return {emptyinfo};

	vector<info> f{emptyinfo};
	v[0] = emptyinfo;
	for (int i = 1; i != n; i++)
		l[i] = i - 1, r[i] = i + 1, v[i] = e[max(a[i - 1], a[i])];
	r[0] = 1, l[0] = n;
	r[n] = 0, l[n] = n - 1;

	for (int i = 0; i != n; i++)
		if (b[i].empty())
			b[i].push_back(emptyinfo);

	int bg = 0;
	auto del = [&](int x) {
		l[r[x]] = l[x], r[l[x]] = r[x];
		if (x == bg)
			bg = r[x];
		v[x] = mr(v[x], b[x].back());
		if (x)
			v[r[x]] = mc(v[x], v[r[x]]);
		else
			v[r[x]] = mr(v[r[x]], v[x]);
	};

	if(b[0].size() <= 1)
		del(0);

	for (int len = 1; len <= m; len++) {
		info x = emptyinfo;
		for (int i = bg; i <= len && i < n; i = r[i]) {
			if (len - i == (int)b[i].size() - 1 && r[i] <= len && i != n - 1) {
				del(i);
				continue;
			}
			if (l[i])
				x = mc(x, v[i]);
			else
				x = mr(v[i], x);
			x = mr(x, getv(b[i], len - i));
			if (len - i == (int)b[i].size() - 1 && i != n - 1)
				del(i);
		}

		f.push_back(x);

		if (bg == n - 1 && len - (n - 1) >= (int)b[n - 1].size() - 1)
			return f;
	}
	return f;
}

vector<info> merge(vector<info> a, vector<info> b, bool op) {
	if (a.size() > b.size())
		swap(a, b);
	if (op) {
		for (int i = 0; i != (int)b.size(); i++)
			b[i] = mr(b[i], getv(a, i));
		return b;
	}
	for (int i = 0; i != (int)a.size(); i++)
		a[i] = mr(a[i], getv(b, i));
	return a;
}

