info ask(int u, int d) {
	for (int i = 17; i != -1; i--) {
		int j = fa[u][i];
		if (!j)
			continue;
		if (h[j] + 1 < d - (1 << i)) {
			u = fa[u][i];
			d -= 1 << i;
		}
	}
	if (fa[u][0] && h[u] + 1 < d)
		d--, u = fa[u][0];
	if (u == 1)
		return getv(dp[1], d);

	return seg[mp[top[u]]].query(h[top[u]] - h[u], d);
}

