		int mx=0;
		for(int v:g[u])if(v!=f){
			cck(v,u);
			mx=max(mx,itt[v]+1);
		}
		itt[u]=mx;
		multiset<int> s;
		for(int v:g[u])if(v!=f)s.insert(itt[v]+1);
		for(int v:g[u])if(v!=f){
			s.erase(s.find(itt[v]+1));
			itmpmx[v]=s.empty()?1:*s.rbegin();
			s.insert(itt[v]+1);
		}
	}else{
		int mx=itmpmx[f];
		if(fa[u])cck(fa[u],u),mx=max(mx,ott[u]+1);
		ott[f]=mx;
	}
}
